-- Map typed country names onto the ISO code the registration menu stores.
-- Safe to run more than once: a row already holding the code is left alone.
-- An unrecognized value is not changed.
-- This file names countries only. It contains no student.

UPDATE students SET country = 'AF' WHERE country IS NOT NULL AND country <> 'AF' AND (lower(trim(country)) IN ('af', 'afghanistan', 'afganistán') OR replace(replace(replace(replace(lower(trim(country)), ' ', ''), '.', ''), '-', ''), '''', '') IN ('af', 'afghanistan', 'afganistan'));
